 * Contact Form Validation
 * Provides client-side validation for required fields and format checking.
 */

const form = document.getElementById('contactForm');
const fullNameField = document.getElementById('fullName');
const emailField = document.getElementById('email');
const phoneField = document.getElementById('phone');
const successMessage = document.getElementById('successMessage');

// Validation rules
const validators = {
  fullName: {
    validate: (value) => {
      const trimmed = value.trim();
      if (!trimmed) return { valid: false, message: 'Error: Full name is required.' };
      if (trimmed.length < 2) return { valid: false, message: 'Error: Full name must be at least 2 characters.' };
      return { valid: true, message: '' };
    }
  },
  email: {
    validate: (value) => {
      const trimmed = value.trim();
      if (!trimmed) return { valid: false, message: 'Error: Email address is required.' };
      // Basic email validation pattern
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(trimmed)) {
        return { valid: false, message: 'Error: Enter a valid email like name@example.com.' };
      }
      return { valid: true, message: '' };
    }
  },
  phone: {
    validate: (value) => {
      const trimmed = value.trim();
      // Phone is optional
      if (!trimmed) return { valid: true, message: '' };
      // Extract digits only and verify we have at least 10 digits
      const digitsOnly = trimmed.replace(/\D/g, '');
      if (digitsOnly.length < 10 || digitsOnly.length > 15) {
        return { valid: false, message: 'Error: Enter a valid phone number like (123) 456-7890.' };
      }
      // Verify it has the general structure of a phone number (flexible formatting)
      // Allows: (123) 456-7890, +1 (123) 456-7890, 123-456-7890, 1234567890, etc.
      const phoneRegex = /^[\+]?[\s]?[\d]?[\s\(\)]?[\d]{3}[\s\)\(\.\-]?[\d]{3}[\s\.\-]?[\d]{4}$/;
      if (!phoneRegex.test(trimmed)) {
        return { valid: false, message: 'Error: Enter a valid phone number like (123) 456-7890.' };
      }
      return { valid: true, message: '' };
    }
  }
};

/**
 * Validates a single field and updates its error state
 */
function validateField(fieldName, fieldElement, errorElement) {
  const validator = validators[fieldName];
  if (!validator) return true;

  const result = validator.validate(fieldElement.value);

  if (result.valid) {
    fieldElement.setAttribute('aria-invalid', 'false');
    errorElement.textContent = '';
  } else {
    fieldElement.setAttribute('aria-invalid', 'true');
    errorElement.textContent = result.message;
  }

  return result.valid;
}

/**
 * Clears all error messages
 */
function clearErrors() {
  successMessage.setAttribute('aria-hidden', 'true');
  document.getElementById('fullName-error').textContent = '';
  document.getElementById('email-error').textContent = '';
  document.getElementById('phone-error').textContent = '';
  fullNameField.setAttribute('aria-invalid', 'false');
  emailField.setAttribute('aria-invalid', 'false');
  phoneField.setAttribute('aria-invalid', 'false');
}

/**
 * Form submission handler
 */
form.addEventListener('submit', (event) => {
  event.preventDefault();
  clearErrors();

  // Validate all fields
  const isFullNameValid = validateField('fullName', fullNameField, document.getElementById('fullName-error'));
  const isEmailValid = validateField('email', emailField, document.getElementById('email-error'));
  const isPhoneValid = validateField('phone', phoneField, document.getElementById('phone-error'));

  // If any field is invalid, focus the first invalid field
  if (!isFullNameValid) {
    fullNameField.focus();
    return;
  }
  if (!isEmailValid) {
    emailField.focus();
    return;
  }
  if (!isPhoneValid) {
    phoneField.focus();
    return;
  }

  // All fields are valid - show success message
  successMessage.setAttribute('aria-hidden', 'false');

  // Reset form after brief delay
  setTimeout(() => {
    form.reset();
    clearErrors();
    fullNameField.focus();
  }, 2000);
});

// Real-time validation as user types
fullNameField.addEventListener('blur', () => {
  validateField('fullName', fullNameField, document.getElementById('fullName-error'));
});

emailField.addEventListener('blur', () => {
  validateField('email', emailField, document.getElementById('email-error'));
});

phoneField.addEventListener('blur', () => {
  validateField('phone', phoneField, document.getElementById('phone-error'));
});

// Clear error on input (while typing)
fullNameField.addEventListener('input', () => {
  if (fullNameField.getAttribute('aria-invalid') === 'true') {
    const result = validators.fullName.validate(fullNameField.value);
    if (result.valid) {
      fullNameField.setAttribute('aria-invalid', 'false');
      document.getElementById('fullName-error').textContent = '';
    }
  }
});

