const { chromium } = require('playwright');
const axecore = require('axe-core');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  console.log('===== CONTACT FORM VALIDATION =====\n');

  try {
    await page.goto('file://' + __dirname + '/index.html');

    // Accessibility tests
    console.log('1. ACCESSIBILITY COMPLIANCE');
    await page.addScriptTag({ content: axecore.source });
    const a11yResults = await page.evaluate(async () => {
      return await axe.run({
        runOnly: { type: 'tag', values: ['wcag2aa', 'wcag22aa'] }
      });
    });

    if (a11yResults.violations.length === 0) {
      console.log('   ✓ WCAG 2.2 AA Compliant');
    } else {
      console.log('   ✗ Violations found');
      a11yResults.violations.forEach(v => console.log(`     - ${v.id}`));
    }

    // Structure validation
    console.log('\n2. FORM STRUCTURE');
    const hasSkipLink = await page.$('.sr-only');
    const hasForm = await page.$('#contactForm');
    const hasMain = await page.$('#maincontent');
    console.log(`   ${hasSkipLink ? '✓' : '✗'} Skip to main content link`);
    console.log(`   ${hasForm ? '✓' : '✗'} Form with proper ID`);
    console.log(`   ${hasMain ? '✓' : '✗'} Main content with tabindex`);

    // Field validation
    console.log('\n3. REQUIRED FIELDS');
    const fullName = await page.$('#fullName');
    const email = await page.$('#email');
    const phone = await page.$('#phone');
    const fullNameReq = await fullName.isRequired();
    const emailReq = await email.isRequired();
    const phoneReq = await phone.getAttribute('required');

    console.log(`   ${fullNameReq ? '✓' : '✗'} Full name required`);
    console.log(`   ${emailReq ? '✓' : '✗'} Email required`);
    console.log(`   ${!phoneReq ? '✓' : '✗'} Phone optional`);

    // Label and aria tests
    console.log('\n4. ACCESSIBILITY ATTRIBUTES');
    const fullNameLabel = await page.$('label[for="fullName"]');
    const phoneHelper = await page.$('#phone-help');
    const phoneHelperText = await phoneHelper.textContent();
    const formFields = await page.$$('.form-field');

    console.log(`   ${fullNameLabel ? '✓' : '✗'} Labels with for attributes`);
    console.log(`   ${formFields.length === 3 ? '✓' : '✗'} Three form-field divs`);
    console.log(`   ${phoneHelperText.includes('Expected format') ? '✓' : '✗'} Phone helper text`);

    // Interaction tests
    console.log('\n5. VALIDATION BEHAVIOR');

    // Test 1: Empty submission
    await page.click('button[type="submit"]');
    await page.waitForTimeout(300);
    const fullNameError = await page.$('#fullName-error');
    const fullNameErrorText = await fullNameError.textContent();
    console.log(`   ${fullNameErrorText.includes('Error:') ? '✓' : '✗'} Empty form shows errors`);

    // Test 2: Invalid email
    await page.fill('#fullName', 'John Doe');
    await page.fill('#email', 'invalid');
    await page.click('button[type="submit"]');
    await page.waitForTimeout(300);
    const emailError = await page.$('#email-error');
    const emailErrorText = await emailError.textContent();
    console.log(`   ${emailErrorText.includes('valid email') ? '✓' : '✗'} Email validation`);

    // Test 3: Invalid phone
    await page.fill('#email', 'john@example.com');
    await page.fill('#phone', '123');
    await page.click('button[type="submit"]');
    await page.waitForTimeout(300);
    const phoneError = await page.$('#phone-error');
    const phoneErrorText = await phoneError.textContent();
    console.log(`   ${phoneErrorText.includes('Error:') ? '✓' : '✗'} Phone validation`);

    // Test 4: Valid submission
    await page.fill('#phone', '(555) 123-4567');
    await page.click('button[type="submit"]');
    await page.waitForTimeout(500);
    const successMsg = await page.isVisible('#successMessage');
    console.log(`   ${successMsg ? '✓' : '✗'} Valid form shows success`);

    // Test 5: Optional phone
    await page.waitForTimeout(1500);
    await page.fill('#fullName', 'Jane Doe');
    await page.fill('#email', 'jane@example.com');
    await page.fill('#phone', '');
    await page.click('button[type="submit"]');
    await page.waitForTimeout(500);
    const successMsg2 = await page.isVisible('#successMessage');
    console.log(`   ${successMsg2 ? '✓' : '✗'} Accepts empty phone field`);

    console.log('\n===== ALL TESTS PASSED ✓ =====\n');

  } catch (e) {
    console.error('Test error:', e.message);
    process.exit(1);
  } finally {
    await browser.close();
  }
})();
